let a0=AccountInfo::new(&k0,s0,w0,&mut l0,&mut d0,&o0,e0,kani::any());
let m0=model::Account{key:k0.to_bytes(),owner:o0.to_bytes(),signer:s0,writable:w0,executable:e0};
let before0=(**a0.lamports.borrow(),a0.data.borrow().to_vec());
