let before1=(**a1.lamports.borrow(),a1.data.borrow().to_vec());
let k2=Pubkey::new_from_array(kani::any());let o2=Pubkey::new_from_array(kani::any());
let mut l2:u64=kani::any();let mut d2:[u8;3]=kani::any();
