assert!(**a2.lamports.borrow()==before2.0);assert!(*a2.data.borrow()==before2.1.as_slice());assert!(a2.key==&k2&&a2.owner==&o2&&a2.is_signer==s2&&a2.is_writable==w2&&a2.executable==e2);
}
